#!/usr/bin/env python3
# Generated by Phase: SETUP | Feature: EVOL-042
"""measure — the project's SDLC cost, read from local data only.

Reads Claude Code session transcripts (JSONL under ~/.claude/projects/<repo-slug>/),
the git log and the per-feature worklog, and reports for a time window:

  gates        wall-clock under each gate class and its share of active agent clock
  branches     commits and review rounds per branch (one branch = one pull request)
  rework       share of rework commits and of repeated edits
  governance   bytes emitted by hooks vs bytes delivered to the model vs bytes read
  agents       per agent: model, tokens, bytes read, citations
  citations    per law / defect-class id; ids never cited = pruning candidates (user decides)

Nothing leaves the machine. A missing data source degrades that section to
`unavailable: <reason>`; it never fails the report. Exit 0 report written · 2 the tool
could not do its job (bad config, unresolved placeholders, unreadable repo).

  python3 subproducts/measure/measure.py                      # markdown, last report_interval_days
  python3 subproducts/measure/measure.py --json --out before.json
  python3 subproducts/measure/measure.py --compare before.json   # before/after protocol
  python3 subproducts/measure/measure.py --selftest
"""
from __future__ import annotations

import argparse
import collections
import datetime as dt
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

SCHEMA = "measure_report_v1"
CONFIG_SCHEMA = "measure_config_v1"
ISO = "%Y-%m-%dT%H:%M:%S.%fZ"
ID_KINDS = ("LAW", "PLAW", "DC")


# ─── config ────────────────────────────────────────────────────────────────────

class ToolFault(Exception):
    """The tool cannot do its job. Message is plain language (LAW-08)."""


def load_config(path: Path) -> dict:
    if not path.is_file():
        raise ToolFault(f"config not found: {path}")
    text = path.read_text(encoding="utf-8")
    if "{{" in text:
        raise ToolFault(f"config has unresolved placeholders: {path} — SETUP --generate resolves them")
    try:
        cfg = json.loads(text)
    except json.JSONDecodeError as e:
        raise ToolFault(f"config is not JSON: {path} ({e.msg} at line {e.lineno})") from None
    if cfg.get("$schema") != CONFIG_SCHEMA:
        raise ToolFault(f"config schema must be {CONFIG_SCHEMA}: {path}")
    for key in ("retention_days", "report_interval_days"):
        if not isinstance(cfg.get(key), int) or cfg[key] <= 0:
            raise ToolFault(f"config key {key} must be a positive integer: {path}")
    return cfg


def repo_slug(repo: Path) -> str:
    """Claude Code names the transcript folder after the absolute path, non-alphanumerics → '-'."""
    return re.sub(r"[^A-Za-z0-9]", "-", str(repo.resolve()))


# ─── transcript reading ─────────────────────────────────────────────────────────

def parse_ts(value) -> dt.datetime | None:
    if not isinstance(value, str):
        return None
    for fmt in (ISO, "%Y-%m-%dT%H:%M:%SZ"):
        try:
            return dt.datetime.strptime(value, fmt).replace(tzinfo=dt.timezone.utc)
        except ValueError:
            continue
    return None


def read_jsonl(path: Path):
    try:
        with path.open(encoding="utf-8", errors="replace") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    yield json.loads(line)
                except json.JSONDecodeError:
                    continue
    except OSError:
        return


def text_len(content) -> int:
    if isinstance(content, str):
        return len(content)
    if isinstance(content, list):
        return sum(text_len(c.get("text", "")) if isinstance(c, dict) else text_len(c) for c in content)
    if isinstance(content, dict):
        return text_len(content.get("text", ""))
    return 0


def assistant_text(msg: dict) -> str:
    content = msg.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "\n".join(c.get("text", "") for c in content if isinstance(c, dict) and c.get("type") == "text")
    return ""


class Session:
    """One transcript file, reduced to what the report needs."""

    def __init__(self, path: Path, cfg: dict, since: dt.datetime, until: dt.datetime):
        self.path = path
        self.id = path.stem
        self.cfg = cfg
        self.since, self.until = since, until
        self.entries = 0
        self.first_ts = self.last_ts = None
        self.active_s = 0.0
        self.tool_uses: dict[str, dict] = {}       # id → {name, input, ts, branch}
        self.tool_durations: list[tuple[str, dict, float, str]] = []  # (name, input, seconds, branch)
        self.hook_events: list[dict] = []
        self.reads: list[tuple[str, int]] = []     # (file_path, bytes)
        self.edits: list[tuple[str, str]] = []     # (branch, file_path)
        self.commits: collections.Counter = collections.Counter()   # branch → git commit tool uses
        self.reviews: collections.Counter = collections.Counter()   # branch → review invocations
        self.text_blocks: list[str] = []
        self.models: collections.Counter = collections.Counter()
        self.tokens = {"input": 0, "output": 0}
        self._load()

    def _in_window(self, ts):
        return ts is not None and self.since <= ts <= self.until

    def _load(self):
        idle_cap = float(self.cfg.get("idle_cap_s", 300))
        prev_ts = None
        for e in read_jsonl(self.path):
            ts = parse_ts(e.get("timestamp"))
            if not self._in_window(ts):
                continue
            self.entries += 1
            self.first_ts = self.first_ts or ts
            self.last_ts = ts
            if prev_ts is not None:
                self.active_s += min((ts - prev_ts).total_seconds(), idle_cap)
            prev_ts = ts
            branch = e.get("gitBranch") or "unknown"
            kind = e.get("type")
            if kind == "attachment":
                self._attachment(e.get("attachment") or {})
            elif kind == "assistant":
                self._assistant(e, ts, branch)
            elif kind == "user":
                self._user(e, ts)

    def _attachment(self, a: dict):
        if not str(a.get("type", "")).startswith("hook_"):
            return
        stdout = (a.get("stdout") or "").strip()
        delivered = a.get("content") or ""
        delivered = delivered.strip() if isinstance(delivered, str) else delivered
        self.hook_events.append({
            "hook": a.get("hookName") or a.get("hookEvent") or "?",
            "outcome": a.get("type"),
            "emitted": len(stdout),
            "delivered": len(delivered) if isinstance(delivered, str) else text_len(delivered),
            "exit": a.get("exitCode"),
        })

    def _assistant(self, e: dict, ts, branch: str):
        msg = e.get("message") or {}
        model = msg.get("model")
        if model and not str(model).startswith("<"):
            self.models[model] += 1
        usage = msg.get("usage") or {}
        self.tokens["input"] += int(usage.get("input_tokens") or 0) + int(usage.get("cache_read_input_tokens") or 0) \
            + int(usage.get("cache_creation_input_tokens") or 0)
        self.tokens["output"] += int(usage.get("output_tokens") or 0)
        text = assistant_text(msg)
        if text:
            self.text_blocks.append(text)
        for c in msg.get("content") or []:
            if isinstance(c, dict) and c.get("type") == "tool_use" and c.get("id"):
                inp = c.get("input") or {}
                self.tool_uses[c["id"]] = {"name": c.get("name"), "input": inp, "ts": ts, "branch": branch}
                self._classify_use(c.get("name"), inp, branch)

    def _classify_use(self, name, inp: dict, branch: str):
        if name in ("Edit", "Write", "MultiEdit", "NotebookEdit") and inp.get("file_path"):
            self.edits.append((branch, inp["file_path"]))
        if name == "Bash":
            cmd = str(inp.get("command", ""))
            if re.search(r"\bgit\s+commit\b", cmd):
                self.commits[branch] += 1
            if any(re.search(p, cmd) for p in self.cfg.get("review_patterns", [])):
                self.reviews[branch] += 1
        if name == "Agent":
            probe = " ".join(str(inp.get(k, "")) for k in ("subagent_type", "description"))
            if any(re.search(p, probe) for p in self.cfg.get("review_agent_patterns", [])):
                self.reviews[branch] += 1

    def _user(self, e: dict, ts):
        msg = e.get("message") or {}
        content = msg.get("content")
        if not isinstance(content, list):
            return
        for c in content:
            if not (isinstance(c, dict) and c.get("type") == "tool_result"):
                continue
            use = self.tool_uses.get(c.get("tool_use_id"))
            if not use:
                continue
            seconds = max(0.0, (ts - use["ts"]).total_seconds()) if use["ts"] else 0.0
            self.tool_durations.append((use["name"], use["input"], seconds, use["branch"]))
            if use["name"] == "Read" and use["input"].get("file_path"):
                self.reads.append((use["input"]["file_path"], text_len(c.get("content"))))
            elif use["name"] == "Bash":
                # a read done through the shell (cat / sed -n / head) counts for the file it names
                cmd = str(use["input"].get("command", ""))
                if re.search(r"\b(cat|sed|head|tail|less|grep)\b", cmd):
                    for token in re.findall(r"[\w./-]+\.(?:md|json|yml|yaml)", cmd):
                        self.reads.append((token, text_len(c.get("content"))))
                        break


def load_subagents(transcripts: Path, session_id: str, cfg, since, until) -> list[dict]:
    out = []
    for f in sorted((transcripts / session_id / "subagents").glob("agent-*.jsonl")):
        meta = {}
        mp = f.with_suffix(".meta.json")
        if mp.is_file():
            try:
                meta = json.loads(mp.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                meta = {}
        s = Session(f, cfg, since, until)
        if s.entries == 0:
            continue
        out.append({"session": session_id, "agent": f.stem.replace("agent-", ""), "type": meta.get("agentType") or "?",
                    "description": meta.get("description") or "", "model": _top(s.models),
                    "tokens_in": s.tokens["input"], "tokens_out": s.tokens["output"],
                    "bytes_read": sum(b for _, b in s.reads),
                    "duration_s": round((s.last_ts - s.first_ts).total_seconds(), 1) if s.first_ts else 0,
                    "citations": count_ids("\n".join(s.text_blocks))})
    return out


def _top(counter: collections.Counter) -> str:
    return counter.most_common(1)[0][0] if counter else "unknown"


# ─── ids / corpus ───────────────────────────────────────────────────────────────

ID_RE = re.compile(r"\b(?:P?LAW|DC)-\d{1,3}\b")


def count_ids(text: str) -> dict[str, int]:
    return dict(collections.Counter(ID_RE.findall(text)))


def corpus_ids(repo: Path, cfg: dict) -> set[str]:
    """Ids DEFINED in the governance corpus: `[LAW-NN]`, `## [PLAW-NN]`, `| DC-NN |` / `### DC-NN`."""
    ids: set[str] = set()
    define = re.compile(r"(?m)(?:^\s*\d+\.\s*\*\*\[|^##+\s*\[|^\|\s*\**)((?:P?LAW|DC)-\d{1,3})")
    for rel in cfg.get("corpus_files", []):
        for p in repo.glob(rel):
            if p.is_file():
                try:
                    ids.update(define.findall(p.read_text(encoding="utf-8", errors="replace")))
                except OSError:
                    continue
    return ids


# ─── git ────────────────────────────────────────────────────────────────────────

def git(repo: Path, *args) -> str | None:
    try:
        r = subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, timeout=60)
    except (OSError, subprocess.TimeoutExpired):
        return None
    return r.stdout if r.returncode == 0 else None


def rework_from_git(repo: Path, cfg: dict, since, until) -> dict:
    log = git(repo, "log", "--no-merges", f"--since={since.isoformat()}", f"--until={until.isoformat()}", "--format=%s")
    if log is None:
        return {"unavailable": "git log not readable (not a repository, or git missing)"}
    subjects = [s for s in log.splitlines() if s.strip()]
    types = tuple(cfg.get("rework_commit_types", ["fix", "revert"]))
    rework = [s for s in subjects if re.match(r"^(%s)(\(|!|:)" % "|".join(map(re.escape, types)), s)]
    return {"commits": len(subjects), "rework_commits": len(rework),
            "share": round(len(rework) / len(subjects), 3) if subjects else None}


# ─── report ─────────────────────────────────────────────────────────────────────

def build_report(repo: Path, cfg: dict, transcripts: Path | None, since, until) -> dict:
    report = {"schema": SCHEMA, "window": {"since": since.isoformat(), "until": until.isoformat(),
                                             "days": round((until - since).total_seconds() / 86400, 1),
                                             "sources": {}, "sessions": 0}}
    sessions: list[Session] = []
    agents: list[dict] = []
    if transcripts and transcripts.is_dir():
        for f in sorted(transcripts.glob("*.jsonl")):
            s = Session(f, cfg, since, until)
            if s.entries:
                sessions.append(s)
                agents.extend(load_subagents(transcripts, s.id, cfg, since, until))
        report["window"]["sources"]["transcripts"] = f"ok ({transcripts})" if sessions else \
            f"unavailable: no session in window under {transcripts}"
    else:
        report["window"]["sources"]["transcripts"] = f"unavailable: folder not found ({transcripts})"
    report["window"]["sessions"] = len(sessions)

    rework_git = rework_from_git(repo, cfg, since, until)
    report["window"]["sources"]["git"] = "ok" if "unavailable" not in rework_git else rework_git["unavailable"]

    if not sessions:
        why = "no transcript data in window"
        report.update({"gates": {"unavailable": why}, "branches": {"unavailable": why},
                       "governance_bytes": {"unavailable": why}, "agents": {"unavailable": why},
                       "citations": {"unavailable": why}})
        report["rework"] = {"git": rework_git, "edits": {"unavailable": why}}
        return report

    # gates
    gate_classes = cfg.get("gates", {})
    by_gate = {k: {"runs": 0, "seconds": 0.0} for k in gate_classes}
    active = sum(s.active_s for s in sessions)
    under = 0.0
    for s in sessions:
        for name, inp, seconds, _ in s.tool_durations:
            if name != "Bash":
                continue
            cmd = str(inp.get("command", ""))
            for klass, patterns in gate_classes.items():
                if any(re.search(p, cmd) for p in patterns):
                    by_gate[klass]["runs"] += 1
                    by_gate[klass]["seconds"] += seconds
                    under += seconds
                    break
    for v in by_gate.values():
        v["seconds"] = round(v["seconds"], 1)
    report["gates"] = {"active_agent_clock_s": round(active, 1), "under_gates_s": round(under, 1),
                       "share": round(under / active, 3) if active else None, "by_gate": by_gate,
                       "definition": "active clock = sum of gaps between consecutive transcript entries, each capped at idle_cap_s; "
                                     "under gates = wall-clock of Bash tool calls matching a gate pattern"}

    # branches (one branch = one pull request)
    branches: dict[str, dict] = {}
    for s in sessions:
        for b, n in s.commits.items():
            branches.setdefault(b, {"commits": 0, "review_rounds": 0})["commits"] += n
        for b, n in s.reviews.items():
            branches.setdefault(b, {"commits": 0, "review_rounds": 0})["review_rounds"] += n
    real = {b: v for b, v in branches.items() if b not in ("unknown", "main", "master")}
    report["branches"] = {
        "per_branch": real,
        "avg_commits": round(sum(v["commits"] for v in real.values()) / len(real), 2) if real else None,
        "avg_review_rounds": round(sum(v["review_rounds"] for v in real.values()) / len(real), 2) if real else None}

    # rework: git types + repeated edits
    per_file: collections.Counter = collections.Counter((b, f) for s in sessions for b, f in s.edits)
    total_edits = sum(per_file.values())
    repeated = sum(n - 1 for n in per_file.values() if n > 1)
    report["rework"] = {"git": rework_git,
                        "edits": {"total": total_edits, "repeated": repeated,
                                  "share": round(repeated / total_edits, 3) if total_edits else None}}

    # governance bytes
    by_hook: dict[str, dict] = {}
    emitted = delivered = truncated = undelivered = 0
    for s in sessions:
        for h in s.hook_events:
            row = by_hook.setdefault(h["hook"], {"fired": 0, "emitted": 0, "delivered": 0, "truncated": 0, "undelivered": 0})
            row["fired"] += 1
            row["emitted"] += h["emitted"]
            row["delivered"] += h["delivered"]
            emitted += h["emitted"]
            delivered += h["delivered"]
            if h["emitted"] and h["delivered"] == 0:          # fired, wrote to stdout, nothing reached the model
                row["undelivered"] += 1
                undelivered += 1
            elif h["emitted"] and h["delivered"] < h["emitted"]:
                row["truncated"] += 1
                truncated += 1
    gov_paths = tuple(cfg.get("governance_paths", []))
    read_bytes = sum(b for s in sessions for f, b in s.reads if _is_governance(f, repo, gov_paths))
    report["governance_bytes"] = {"emitted_by_hooks": emitted, "delivered_to_model": delivered,
                                  "truncated_deliveries": truncated, "undelivered_firings": undelivered,
                                  "read_by_agents": read_bytes, "by_hook": by_hook,
                                  "definition": "emitted = hook stdout bytes; delivered = bytes that reached the model's context; "
                                                "undelivered = fired with stdout but nothing delivered (wrong channel); "
                                                "read = tool-result bytes of Read (or cat/sed/head through Bash) on governance paths"}

    # agents (main sessions + subagents)
    rows = [{"session": s.id, "agent": "main", "type": "main", "description": "", "model": _top(s.models),
             "tokens_in": s.tokens["input"], "tokens_out": s.tokens["output"],
             "bytes_read": sum(b for _, b in s.reads),
             "duration_s": round((s.last_ts - s.first_ts).total_seconds(), 1) if s.first_ts else 0,
             "citations": count_ids("\n".join(s.text_blocks))} for s in sessions] + agents
    report["agents"] = rows

    # citations
    cited: collections.Counter = collections.Counter()
    for r in rows:
        cited.update(r["citations"])
    corpus = corpus_ids(repo, cfg)
    report["citations"] = {"by_id": dict(sorted(cited.items())),
                           "corpus_ids": len(corpus),
                           "pruning_candidates": sorted(corpus - set(cited)),
                           "note": "a pruning candidate is decided by the user through RDR with the originating record in view; never deleted by a script"}
    return report


def _is_governance(file_path: str, repo: Path, gov_paths) -> bool:
    p = file_path
    try:
        p = str(Path(file_path).resolve().relative_to(repo.resolve()))
    except (ValueError, OSError):
        pass
    return any(p == g or p.startswith(g.rstrip("/") + "/") or Path(p).match(g) for g in gov_paths)


# ─── compare (before / after) ─────────────────────────────────────────────────────

SCALARS = (("gates", "share"), ("branches", "avg_commits"), ("branches", "avg_review_rounds"),
           ("rework", "edits", "share"), ("governance_bytes", "emitted_by_hooks"),
           ("governance_bytes", "delivered_to_model"), ("governance_bytes", "read_by_agents"))


def dig(d, *keys):
    for k in keys:
        d = d.get(k) if isinstance(d, dict) else None
    return d


def compare(before: dict, after: dict) -> dict:
    if before.get("schema") != SCHEMA:
        raise ToolFault("the baseline file is not a measure report (schema mismatch)")
    rows = {}
    for keys in SCALARS:
        b, a = dig(before, *keys), dig(after, *keys)
        rows[".".join(keys)] = {"before": b, "after": a,
                                "delta": round(a - b, 3) if isinstance(a, (int, float)) and isinstance(b, (int, float)) else None}
    git_b, git_a = dig(before, "rework", "git", "share"), dig(after, "rework", "git", "share")
    rows["rework.git.share"] = {"before": git_b, "after": git_a,
                                "delta": round(git_a - git_b, 3) if isinstance(git_a, (int, float)) and isinstance(git_b, (int, float)) else None}
    return rows


# ─── markdown ───────────────────────────────────────────────────────────────────

def _fmt(v):
    if v is None:
        return "—"
    if isinstance(v, float):
        return f"{v:.3f}" if v < 10 else f"{v:,.1f}"
    return str(v)


def render_markdown(r: dict, delta: dict | None = None) -> str:
    w = r["window"]
    out = [f"# SDLC measurement — {w['since'][:10]} → {w['until'][:10]} ({w['days']} days, {w['sessions']} sessions)", ""]
    out += [f"- {k}: {v}" for k, v in w["sources"].items()] + [""]

    def section(title, block, rows):
        out.append(f"## {title}")
        if isinstance(block, dict) and "unavailable" in block:
            out.append(f"unavailable: {block['unavailable']}")
        else:
            out.extend(rows)
        out.append("")

    g = r["gates"]
    section("Gates", g, [] if "unavailable" in g else
            [f"Active agent clock {_fmt(g['active_agent_clock_s'])} s · under gates {_fmt(g['under_gates_s'])} s · share **{_fmt(g['share'])}**", "",
             "| gate | runs | seconds |", "|---|---|---|"] +
            [f"| {k} | {v['runs']} | {_fmt(v['seconds'])} |" for k, v in g["by_gate"].items()])
    b = r["branches"]
    section("Branches (one branch = one pull request)", b, [] if "unavailable" in b else
            [f"avg commits {_fmt(b['avg_commits'])} · avg review rounds {_fmt(b['avg_review_rounds'])}", "",
             "| branch | commits | review rounds |", "|---|---|---|"] +
            [f"| {k} | {v['commits']} | {v['review_rounds']} |" for k, v in b["per_branch"].items()])
    rw = r["rework"]
    gitp = rw["git"]
    ed = rw["edits"]
    section("Rework", {}, [
        "git: " + (f"unavailable: {gitp['unavailable']}" if "unavailable" in gitp else
                   f"{gitp['rework_commits']} of {gitp['commits']} commits are fix/revert (share {_fmt(gitp['share'])})"),
        "edits: " + (f"unavailable: {ed['unavailable']}" if "unavailable" in ed else
                     f"{ed['repeated']} of {ed['total']} edits hit a file already edited on the same branch (share {_fmt(ed['share'])})")])
    gb = r["governance_bytes"]
    section("Governance bytes", gb, [] if "unavailable" in gb else
            [f"emitted by hooks {gb['emitted_by_hooks']:,} · delivered to the model {gb['delivered_to_model']:,} · "
             f"truncated deliveries {gb['truncated_deliveries']} · undelivered firings {gb['undelivered_firings']} · "
             f"read by agents {gb['read_by_agents']:,}", "",
             "| hook | fired | emitted | delivered | truncated | undelivered |", "|---|---|---|---|---|---|"] +
            [f"| {k} | {v['fired']} | {v['emitted']:,} | {v['delivered']:,} | {v['truncated']} | {v['undelivered']} |" for k, v in gb["by_hook"].items()])
    ag = r["agents"]
    section("Agents", ag if isinstance(ag, dict) else {}, [] if isinstance(ag, dict) else
            ["| session | agent | type | model | tokens in | tokens out | bytes read | seconds | citations |",
             "|---|---|---|---|---|---|---|---|---|"] +
            [f"| {a['session'][:8]} | {a['agent'][:8]} | {a['type']} | {a['model']} | {a['tokens_in']:,} | {a['tokens_out']:,} | "
             f"{a['bytes_read']:,} | {_fmt(a['duration_s'])} | {sum(a['citations'].values())} |" for a in ag])
    c = r["citations"]
    section("Citations", c, [] if "unavailable" in c else
            [f"corpus ids {c['corpus_ids']} · cited {len(c['by_id'])} · pruning candidates {len(c['pruning_candidates'])}", "",
             "| id | citations |", "|---|---|"] + [f"| {k} | {v} |" for k, v in c["by_id"].items()] +
            ["", "Pruning candidates (never cited in the window): " + (", ".join(c["pruning_candidates"]) or "none"),
             "", f"> {c['note']}"])
    if delta is not None:
        out += ["## Before → after", "", "| signal | before | after | delta |", "|---|---|---|---|"]
        out += [f"| {k} | {_fmt(v['before'])} | {_fmt(v['after'])} | {_fmt(v['delta'])} |" for k, v in delta.items()]
        out.append("")
    return "\n".join(out)


# ─── self-test ──────────────────────────────────────────────────────────────────

def _entry(kind, ts, **kw):
    e = {"type": kind, "timestamp": ts, "sessionId": "s1", "gitBranch": kw.pop("branch", "feature/FEAT-001-x")}
    e.update(kw)
    return e


def _fixture_transcripts(root: Path, session="s1") -> Path:
    tdir = root / "projects" / "slug"
    (tdir / session / "subagents").mkdir(parents=True)
    t0 = dt.datetime(2026, 9, 1, 10, 0, 0, tzinfo=dt.timezone.utc)

    def ts(seconds):
        return (t0 + dt.timedelta(seconds=seconds)).strftime(ISO)

    def tool_use(i, name, inp, at):
        return _entry("assistant", ts(at), message={"role": "assistant", "model": "claude-x-writer",
                                                    "usage": {"input_tokens": 10, "output_tokens": 5},
                                                    "content": [{"type": "text", "text": f"Applying LAW-01 and DC-18 (use {i})"},
                                                                {"type": "tool_use", "id": f"t{i}", "name": name, "input": inp}]})

    def tool_result(i, at, content=""):
        return _entry("user", ts(at), message={"role": "user", "content": [{"type": "tool_result", "tool_use_id": f"t{i}", "content": content}]})

    lines = [
        _entry("attachment", ts(0), attachment={"type": "hook_success", "hookName": "SessionStart:startup",
                                                "stdout": "x" * 1000, "content": "x" * 1000, "exitCode": 0}),
        _entry("attachment", ts(1), attachment={"type": "hook_success", "hookName": "UserPromptSubmit",
                                                "stdout": "y" * 5000, "content": "y" * 2000, "exitCode": 0}),
        _entry("attachment", ts(2), attachment={"type": "hook_non_blocking_error", "hookName": "PreToolUse:Edit",
                                                "stdout": "BLOCKED " * 10 + "\n", "content": "", "exitCode": 1}),
        tool_use(1, "Bash", {"command": "bash scripts/validate-governance.sh --base main"}, 10),
        tool_result(1, 70),                                                       # 60 s under a verification gate
        tool_use(2, "Bash", {"command": "ls"}, 80),
        tool_result(2, 81),
        tool_use(3, "Read", {"file_path": "docs/constitution.md"}, 90),
        tool_result(3, 91, "c" * 300),                                            # 300 governance bytes read
        tool_use(4, "Read", {"file_path": "src/app.py"}, 92),
        tool_result(4, 93, "p" * 999),                                            # not governance
        tool_use(10, "Bash", {"command": "sed -n '1,40p' .claude/rules/testing.md"}, 94),
        tool_result(10, 95, "r" * 50),                                            # a governance read through the shell
        tool_use(5, "Edit", {"file_path": "src/app.py"}, 100),
        tool_result(5, 101),
        tool_use(6, "Edit", {"file_path": "src/app.py"}, 110),                     # repeated edit
        tool_result(6, 111),
        tool_use(7, "Bash", {"command": "git commit -m 'feat(FEAT-001): a'"}, 120),
        tool_result(7, 121),
        tool_use(8, "Agent", {"subagent_type": "factory-critic-security", "description": "review"}, 130),
        tool_result(8, 190),
        tool_use(9, "Bash", {"command": "git push"}, 200),
        tool_result(9, 230),                                                      # 30 s under the push gate
    ]
    (tdir / f"{session}.jsonl").write_text("\n".join(json.dumps(e) for e in lines) + "\n", encoding="utf-8")
    sub = [
        _entry("assistant", ts(140), message={"role": "assistant", "model": "claude-y-critic",
                                              "usage": {"input_tokens": 100, "output_tokens": 50},
                                              "content": [{"type": "text", "text": "Finding under LAW-04 and LAW-04."},
                                                          {"type": "tool_use", "id": "a1", "name": "Read", "input": {"file_path": "src/app.py"}}]}),
        _entry("user", ts(150), message={"role": "user", "content": [{"type": "tool_result", "tool_use_id": "a1", "content": "z" * 40}]}),
    ]
    (tdir / session / "subagents" / "agent-c1.jsonl").write_text("\n".join(json.dumps(e) for e in sub) + "\n", encoding="utf-8")
    (tdir / session / "subagents" / "agent-c1.meta.json").write_text(json.dumps({"agentType": "factory-critic-security", "description": "review"}), encoding="utf-8")
    return tdir


def _fixture_repo(root: Path) -> Path:
    repo = root / "repo"
    repo.mkdir()
    env = {**os.environ, "GIT_AUTHOR_DATE": "2026-09-02T10:00:00Z", "GIT_COMMITTER_DATE": "2026-09-02T10:00:00Z",
           "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t", "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t"}

    def run(*a):
        subprocess.run(["git", "-C", str(repo), *a], check=True, capture_output=True, env=env)

    run("init", "-q")
    (repo / "CLAUDE.md").write_text("1. **[LAW-01] a**\n2. **[LAW-04] b**\n3. **[LAW-09] c**\n", encoding="utf-8")
    (repo / ".claude" / "rules").mkdir(parents=True)
    (repo / ".claude" / "rules" / "defect-prevention.md").write_text("| DC-18 | x |\n| DC-27 | y |\n", encoding="utf-8")
    for msg in ("feat(FEAT-001): a", "fix(FEAT-001): b", "docs: c"):
        (repo / "f").write_text(msg, encoding="utf-8")
        run("add", "-A")
        run("commit", "-q", "-m", msg)
    return repo


def selftest_config() -> dict:
    return {"$schema": CONFIG_SCHEMA, "retention_days": 90, "report_interval_days": 30, "idle_cap_s": 300,
            "gates": {"verification": [r"validate-governance\.sh", r"\bpytest\b"], "push": [r"\bgit\s+push\b"]},
            "review_patterns": [r"preflight\.sh"], "review_agent_patterns": [r"critic"],
            "governance_paths": ["docs/constitution.md", "CLAUDE.md", ".claude/rules/"],
            "corpus_files": ["CLAUDE.md", ".claude/rules/defect-prevention.md"], "rework_commit_types": ["fix", "revert"]}


def selftest() -> int:
    failures: list[str] = []

    def expect(cond, label):
        (failures.append(label) if not cond else None)
        print(("  ✓ " if cond else "  ✗ ") + label)

    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp)
        tdir = _fixture_transcripts(root)
        repo = _fixture_repo(root)
        cfg = selftest_config()
        since = dt.datetime(2026, 8, 31, tzinfo=dt.timezone.utc)
        until = dt.datetime(2026, 9, 30, tzinfo=dt.timezone.utc)
        r = build_report(repo, cfg, tdir, since, until)
        expect(r["window"]["sessions"] == 1, "one session read in window")
        expect(r["gates"]["by_gate"]["verification"] == {"runs": 1, "seconds": 60.0}, "verification gate: 1 run, 60 s")
        expect(r["gates"]["by_gate"]["push"] == {"runs": 1, "seconds": 30.0}, "push gate: 1 run, 30 s")
        expect(r["gates"]["under_gates_s"] == 90.0 and r["gates"]["share"] is not None and 0 < r["gates"]["share"] < 1,
               "share of active clock under gates computed from tool wall-clock")
        b = r["branches"]["per_branch"]["feature/FEAT-001-x"]
        expect(b == {"commits": 1, "review_rounds": 1}, "commits and review rounds counted per branch")
        expect(r["rework"]["git"] == {"commits": 3, "rework_commits": 1, "share": 0.333}, "rework share from git commit types")
        expect(r["rework"]["edits"] == {"total": 2, "repeated": 1, "share": 0.5}, "repeated-edit share from Edit tool uses")
        gb = r["governance_bytes"]
        expect(gb["emitted_by_hooks"] == 6079 and gb["delivered_to_model"] == 3000, "hook bytes: emitted vs delivered")
        expect(gb["truncated_deliveries"] == 1, "a delivery shorter than its stdout is a truncation")
        expect(gb["undelivered_firings"] == 1 and gb["by_hook"]["PreToolUse:Edit"]["undelivered"] == 1,
               "a hook that fires with stdout but delivers nothing is counted as undelivered")
        expect(gb["read_by_agents"] == 350, "governance bytes read count Read and shell reads on governance paths only")
        ag = {a["agent"]: a for a in r["agents"]}
        expect(ag["main"]["model"] == "claude-x-writer" and ag["c1"]["model"] == "claude-y-critic", "model per agent")
        expect(ag["c1"]["type"] == "factory-critic-security" and ag["c1"]["bytes_read"] == 40 and ag["c1"]["tokens_in"] == 100,
               "subagent type, bytes read and tokens from its own transcript")
        expect(ag["c1"]["citations"] == {"LAW-04": 2}, "citations per agent")
        c = r["citations"]
        expect(c["by_id"].get("LAW-01") == 10 and c["by_id"].get("LAW-04") == 2, "citations aggregated across agents")
        expect(c["pruning_candidates"] == ["DC-27", "LAW-09"], "corpus ids never cited are pruning candidates")
        md = render_markdown(r)
        expect("## Gates" in md and "pruning candidates 2" in md, "markdown rendering")
        d = compare(r, r)
        expect(all(v["delta"] == 0 for v in d.values() if v["delta"] is not None), "compare of a report with itself is zero delta")
        # degradation: no transcripts, no git
        r2 = build_report(root / "nope", cfg, root / "missing", since, until)
        expect(r2["window"]["sources"]["transcripts"].startswith("unavailable"), "missing transcripts folder is said, not raised")
        expect("unavailable" in r2["rework"]["git"], "missing git is said, not raised")
        expect("unavailable" in r2["gates"] and "unavailable" in r2["citations"], "sections degrade to unavailable")
        expect("unavailable" in render_markdown(r2), "partial report still renders")
        # config faults are tool faults in plain language
        bad = root / "bad.json"
        bad.write_text('{"$schema": "measure_config_v1", "retention_days": "{{measure-x}}"}', encoding="utf-8")
        try:
            load_config(bad)
            expect(False, "unresolved placeholder refused")
        except ToolFault as e:
            expect("unresolved placeholders" in str(e), "unresolved placeholder refused in plain language")
        try:
            compare({"schema": "other"}, r)
            expect(False, "baseline with wrong schema refused")
        except ToolFault:
            expect(True, "baseline with wrong schema refused")
    print(f"{len(failures)} failure(s)")
    return 1 if failures else 0


# ─── cli ────────────────────────────────────────────────────────────────────────

def cli(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--repo", default=None, help="repository root (default: git root of the current folder)")
    ap.add_argument("--config", default=None, help="measure.config.json (default: next to this tool)")
    ap.add_argument("--transcripts", default=None, help="Claude Code transcripts folder (default: ~/.claude/projects/<repo-slug>)")
    ap.add_argument("--window-days", type=int, default=None, help="window length (default: report_interval_days)")
    ap.add_argument("--until", default=None, help="window end, ISO date (default: now)")
    ap.add_argument("--json", action="store_true", help="write JSON instead of markdown")
    ap.add_argument("--out", default=None, help="write to this file instead of stdout")
    ap.add_argument("--compare", default=None, help="a JSON report taken before the change; adds the before/after table")
    ap.add_argument("--selftest", action="store_true")
    a = ap.parse_args(argv)
    if a.selftest:
        return selftest()
    here = Path(__file__).resolve().parent
    cfg = load_config(Path(a.config) if a.config else here / "measure.config.json")
    repo = Path(a.repo).resolve() if a.repo else Path(git(Path.cwd(), "rev-parse", "--show-toplevel").strip()) \
        if git(Path.cwd(), "rev-parse", "--show-toplevel") else Path.cwd()
    if not repo.is_dir():
        raise ToolFault(f"repository folder not found: {repo}")
    transcripts = Path(a.transcripts) if a.transcripts else Path.home() / ".claude" / "projects" / repo_slug(repo)
    until = parse_ts(a.until) or (dt.datetime.fromisoformat(a.until).replace(tzinfo=dt.timezone.utc) if a.until else None) \
        or dt.datetime.now(dt.timezone.utc)
    days = a.window_days or int(cfg["report_interval_days"])
    if days > int(cfg["retention_days"]):
        raise ToolFault(f"window of {days} days exceeds retention_days={cfg['retention_days']} (edit measure.config.json)")
    since = until - dt.timedelta(days=days)
    report = build_report(repo, cfg, transcripts, since, until)
    delta = None
    if a.compare:
        try:
            before = json.loads(Path(a.compare).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as e:
            raise ToolFault(f"cannot read the baseline report {a.compare}: {e}") from None
        delta = compare(before, report)
        report["before_after"] = delta
    text = json.dumps(report, indent=2) if a.json else render_markdown(report, delta)
    if a.out:
        Path(a.out).write_text(text + "\n", encoding="utf-8")
        print(f"report written: {a.out}")
    else:
        print(text)
    return 0


def main() -> int:
    try:
        return cli(sys.argv[1:])
    except ToolFault as e:
        print(f"measure: {e}", file=sys.stderr)
        return 2
    except Exception as e:  # LAW-08: never a raw trace unless asked
        if os.environ.get("MEASURE_DEBUG") == "1":
            raise
        print(f"measure: the tool could not do its job ({type(e).__name__}: {e}). Set MEASURE_DEBUG=1 for the trace.", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
